-- Cement hub: experimental post-load UI customization.
-- This does not deobfuscate the virtualized program; it adjusts visible GUI objects after startup.
local __cement_players = game:GetService("Players")
local __cement_player = __cement_players.LocalPlayer
local __cement_orange = Color3.fromRGB(255, 115, 0)
local __cement_black = Color3.fromRGB(8, 8, 8)
local __cement_dark = Color3.fromRGB(20, 12, 6)

local function __cement_text(obj)
    if obj and (obj:IsA("TextLabel") or obj:IsA("TextButton") or obj:IsA("TextBox")) then
        return tostring(obj.Text or "")
    end
    return ""
end

local function __cement_contains_words(root, first, second)
    local has_first, has_second = false, false
    for _, d in ipairs(root:GetDescendants()) do
        local t = __cement_text(d):lower()
        if t:find(first, 1, true) then has_first = true end
        if t:find(second, 1, true) then has_second = true end
    end
    return has_first and has_second
end

local function __cement_recolor(c)
    local r, g, b = c.R, c.G, c.B
    local is_purple = (b > r * 1.12 and b > g * 1.12 and b > 0.12)
        or (r > g * 1.18 and b > g * 1.18 and math.min(r, b) > 0.12)
    if is_purple then
        if math.max(r, g, b) < 0.42 then
            return __cement_black
        end
        return __cement_orange
    end
    return c
end

local function __cement_recolor_ui(root)
    for _, obj in ipairs(root:GetDescendants()) do
        pcall(function()
            if obj:IsA("GuiObject") then
                obj.BackgroundColor3 = __cement_recolor(obj.BackgroundColor3)
            end
            if obj:IsA("TextLabel") or obj:IsA("TextButton") or obj:IsA("TextBox") then
                obj.TextColor3 = __cement_recolor(obj.TextColor3)
            end
            if obj:IsA("ImageLabel") or obj:IsA("ImageButton") then
                obj.ImageColor3 = __cement_recolor(obj.ImageColor3)
            end
            if obj:IsA("UIStroke") then
                obj.Color = __cement_recolor(obj.Color)
            elseif obj:IsA("UIGradient") then
                local keys = {}
                for _, kp in ipairs(obj.Color.Keypoints) do
                    table.insert(keys, ColorSequenceKeypoint.new(kp.Time, __cement_recolor(kp.Value)))
                end
                obj.Color = ColorSequence.new(keys)
            end
        end)
    end
end

local function __cement_remove_start_popup(root)
    for _, obj in ipairs(root:GetDescendants()) do
        if obj:IsA("Frame") and obj.Parent and __cement_contains_words(obj, "discord", "close") then
            -- Only remove a compact popup frame; never destroy a whole ScreenGui or main menu.
            local count = #obj:GetDescendants()
            if count > 0 and count < 80 then
                obj:Destroy()
                return true
            end
        end
    end
    return false
end

local function __cement_remove_scripts_tab(root)
    for _, obj in ipairs(root:GetDescendants()) do
        if (obj:IsA("TextButton") or obj:IsA("ImageButton")) and __cement_text(obj):lower():match("^%s*scripts%s*$") then
            obj:Destroy()
            return true
        end
    end
    return false
end

local function __cement_set_info(root)
    -- Only touch a clearly named Info page container, to avoid rewriting unrelated labels.
    for _, obj in ipairs(root:GetDescendants()) do
        local n = tostring(obj.Name):lower()
        if obj:IsA("Frame") and (n == "info" or n == "infopage" or n == "info_page") then
            local keeper = nil
            for _, d in ipairs(obj:GetDescendants()) do
                if d:IsA("TextLabel") and not keeper then keeper = d end
            end
            if keeper then
                keeper.Text = "Cement hub"
                keeper.Visible = true
                for _, d in ipairs(obj:GetDescendants()) do
                    if d ~= keeper and (d:IsA("TextLabel") or d:IsA("TextButton") or d:IsA("TextBox")) then
                        d.Visible = false
                    end
                end
            end
        end
    end
end

local function __cement_apply()
    if not __cement_player then return end
    local roots = {}
    local pg = __cement_player:FindFirstChildOfClass("PlayerGui")
    if pg then table.insert(roots, pg) end
    pcall(function()
        local cg = game:GetService("CoreGui")
        if cg then table.insert(roots, cg) end
    end)
    for _, root in ipairs(roots) do
        for _, gui in ipairs(root:GetChildren()) do
            if gui:IsA("ScreenGui") then
                pcall(function() __cement_recolor_ui(gui) end)
                pcall(function() __cement_remove_start_popup(gui) end)
                pcall(function() __cement_remove_scripts_tab(gui) end)
                pcall(function() __cement_set_info(gui) end)
            end
        end
    end
end

task.spawn(function()
    for _ = 1, 50 do
        pcall(__cement_apply)
        task.wait(0.3)
    end
end)
